/**
 * Interactive planning diagram. Floor contours come from main-floors.json.
 * The district view is a scenario diagram, not an architectural placement.
 * The generated plan.js prepends the verified, simplified FLOOR_DATA constant.
 */
let nextPlanId = 1;
const NS = 'http://www.w3.org/2000/svg';
const nf = new Intl.NumberFormat('ru-RU', { maximumFractionDigits: 0 });
const nf1 = new Intl.NumberFormat('ru-RU', { maximumFractionDigits: 1 });
const districtNames = ['ДФО', 'СФО', 'УФО', 'ПФО', 'ЦФО', 'СКФО', 'ЮФО', 'СЗФО'];
const finite = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;
const positive = value => Math.max(0, finite(value));
const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
function el(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}
function svgEl(tag, attrs = {}) {
  const node = document.createElementNS(NS, tag);
  for (const [key, value] of Object.entries(attrs)) node.setAttribute(key, String(value));
  return node;
}
function metric(label, unit = '') {
  const group = el('div', 'pp-metric');
  const value = el('strong', 'pp-metric-value', '0');
  group.append(el('span', 'pp-metric-label', label), value);
  if (unit) group.append(el('span', 'pp-metric-unit', unit));
  return { group, value };
}
function areaPerPerson(area, people) {
  return people > 0 ? area / people : null;
}

/**
 * @param {HTMLElement} container
 * @param {{onSelectDistrict?: (index:number)=>void}} options
 * @returns {{update:(state:Object)=>void,destroy:()=>void}}
 */
export function createParkPlan(container, { onSelectDistrict } = {}) {
  if (!(container instanceof HTMLElement)) throw new TypeError('Для схемы нужен HTML-контейнер.');
  const id = `park-plan-${nextPlanId++}`;
  let selected = -1;
  let destroyed = false;
  const root = el('div', 'park-plan');
  root.id = id;
  root.setAttribute('aria-label', 'Схема распределения посетителей и показателей парка');

  const summary = el('div', 'pp-stream');
  const total = metric('В парке одновременно', 'человек');
  const guided = metric('С экскурсией', 'человек');
  const independent = metric('Самостоятельно', 'человек');
  summary.append(total.group, guided.group, independent.group);
  root.append(summary);

  const districtView = el('div', 'pp-district-view');
  const branchLabel = el('p', 'pp-branch-label', 'Этот поток распределяется между восемью округами');
  const districtGrid = el('div', 'pp-district-grid');
  districtGrid.setAttribute('role', 'group');
  districtGrid.setAttribute('aria-label', 'Выберите округ на условной схеме');
  const districts = [];
  for (let i = 0; i < 8; i++) {
    const button = el('button', 'pp-district');
    button.type = 'button';
    button.dataset.district = String(i);
    button.setAttribute('aria-pressed', 'false');
    const heading = el('span', 'pp-district-name', districtNames[i]);
    const top = el('span', 'pp-district-top');
    top.append(heading);
    const metrics = el('span', 'pp-district-metrics');
    const fields = {};
    for (const [key, label] of [['people', 'Посетителей'], ['groups', 'Групп'], ['screens', 'Поверхностей'], ['area', 'Площадь, м²']]) {
      const group = el('span', 'pp-district-stat');
      const value = el('strong', 'pp-district-value', '0');
      group.append(value, el('span', 'pp-district-stat-label', label));
      metrics.append(group);
      fields[key] = value;
    }
    const densityText = el('span', 'pp-district-density', 'Посетителей нет');
    const load = el('span', 'pp-load');
    load.setAttribute('aria-hidden', 'true');
    const fill = el('span', 'pp-load-fill');
    load.append(fill);
    const status = el('span', 'pp-district-status', 'Посетителей нет');
    button.append(top, metrics, densityText, load, status);
    const select = () => {
      if (destroyed || selected === i) return;
      selected = i;
      for (const item of districts) item.button.setAttribute('aria-pressed', String(item.index === i));
      if (typeof onSelectDistrict === 'function') onSelectDistrict(i);
    };
    button.addEventListener('click', select);
    button.addEventListener('focus', select);
    button.addEventListener('pointerenter', event => { if (event.pointerType === 'mouse') select(); });
    districts.push({ index: i, button, heading, fields, densityText, fill, status });
    districtGrid.append(button);
  }
  districtView.append(branchLabel, districtGrid);
  root.append(districtView);

  const floorView = el('div', 'pp-floor-view');
  floorView.hidden = true;
  const floorGrid = el('div', 'pp-floor-grid');
  const floorViews = [];
  for (let i = 0; i < FLOOR_DATA.floors.length; i++) {
    const floor = FLOOR_DATA.floors[i];
    const card = el('article', 'pp-floor');
    const title = el('h3', 'pp-floor-title', floor.name);
    const areaLabel = el('p', 'pp-floor-area', `${nf1.format(floor.area)} м² · по 3D-модели`);
    const svg = svgEl('svg', {
      class: 'pp-floor-svg',
      viewBox: FLOOR_DATA.viewBox,
      role: 'img',
      'aria-labelledby': `${id}-floor-title-${i} ${id}-floor-desc-${i}`,
      preserveAspectRatio: 'xMidYMid meet'
    });
    const svgTitle = svgEl('title', { id: `${id}-floor-title-${i}` });
    svgTitle.textContent = floor.name;
    const svgDesc = svgEl('desc', { id: `${id}-floor-desc-${i}` });
    svgDesc.textContent = 'Контур пола из модели. Расположение меток посетителей условное.';
    const path = svgEl('path', {
      d: floor.path,
      class: 'pp-floor-contour',
      'fill-rule': 'evenodd',
      'vector-effect': 'non-scaling-stroke'
    });
    const dots = svgEl('g', { class: 'pp-floor-dots', 'aria-hidden': 'true' });
    svg.append(svgTitle, svgDesc, path, dots);
    const dataRow = el('div', 'pp-floor-data');
    const people = metric('Одновременно', 'человек');
    const perPerson = metric('Общая площадь', 'м² на человека');
    dataRow.append(people.group, perPerson.group);
    const status = el('p', 'pp-floor-status', 'Посетителей нет');
    const load = el('div', 'pp-load');
    load.setAttribute('aria-hidden', 'true');
    const fill = el('span', 'pp-load-fill');
    load.append(fill);
    card.append(title, areaLabel, svg, dataRow, load, status);
    floorGrid.append(card);
    floorViews.push({ card, svgDesc, dots, people: people.value, perPerson: perPerson.value, status, fill, floor });
  }
  const markerLegend = el('div', 'pp-marker-legend');
  const guidedLegend = el('span', 'pp-legend-guided', 'С экскурсией');
  const independentLegend = el('span', 'pp-legend-independent', 'Самостоятельно');
  const markerUnit = el('span', 'pp-marker-unit', '1 метка ≈ 25 человек');
  markerLegend.append(guidedLegend, independentLegend, markerUnit);
  floorView.append(floorGrid, markerLegend);
  root.append(floorView);

  const note = el('p', 'pp-plan-note', 'Распределение по округам — сценарий; контуры этажей — по 3D-модели.');
  const densityNote = el('p', 'pp-density-note', 'Схемы показывают общую площадь модели: экспонаты и проходы не вычтены. Сравнение доступной площади с выбранным ориентиром приведено в расчётных замечаниях. Полоски показывают долю посетителей, а не допустимую вместимость.');
  root.append(note, densityNote);
  container.append(root);

  function drawDots(group, points, guidedPeople, independentPeople, unit) {
    const guidedCount = Math.min(points.length, Math.ceil(guidedPeople / unit));
    const independentCount = Math.min(points.length - guidedCount, Math.ceil(independentPeople / unit));
    const fragment = document.createDocumentFragment();
    for (let i = 0; i < guidedCount + independentCount; i++) {
      const [x, y] = points[i];
      fragment.append(i < guidedCount
        ? svgEl('circle', { cx: x, cy: y, r: 1.3, class: 'pp-person-guided' })
        : svgEl('rect', { x: x - 1.2, y: y - 1.2, width: 2.4, height: 2.4, rx: 0.35, class: 'pp-person-independent' }));
    }
    group.replaceChildren(fragment);
  }

  function update(state = {}) {
    if (destroyed) return;
    const guide = positive(state.guidedOccupancy);
    const solo = positive(state.independentOccupancy);
    const occupancy = positive(state.totalOccupancy === undefined ? guide + solo : state.totalOccupancy);
    total.value.textContent = nf.format(occupancy);
    guided.value.textContent = nf.format(guide);
    independent.value.textContent = nf.format(solo);
    const list = Array.isArray(state.districts) ? state.districts : [];
    const chosen = Math.trunc(finite(state.selectedDistrict, 0));
    selected = clamp(chosen, 0, 7);
    districts.forEach((item, i) => {
      const d = list[i] || {};
      const people = positive(d.people);
      const area = positive(d.area);
      item.heading.textContent = d.name || districtNames[i];
      item.fields.people.textContent = nf.format(people);
      item.fields.groups.textContent = nf1.format(positive(d.groups));
      item.fields.screens.textContent = nf.format(positive(d.screens));
      item.fields.area.textContent = nf1.format(area);
      item.button.setAttribute('aria-pressed', String(selected === i));
      const space = areaPerPerson(area, people);
      const share = occupancy > 0 ? clamp(people / occupancy * 100, 0, 100) : 0;
      item.densityText.textContent = space === null ? 'Посетителей нет' : `${nf1.format(space)} м² общей площади на человека`;
      item.fill.style.width = `${share}%`;
      item.status.textContent = 'Расчётное распределение';
      item.button.setAttribute('aria-label', `${item.heading.textContent}: ${nf.format(people)} посетителей, ${nf1.format(positive(d.groups))} групп, ${nf.format(positive(d.screens))} поверхностей, ${nf1.format(area)} квадратных метров. Расчётное распределение: ${nf1.format(share)}% посетителей.`);
    });
    const floors = state.view === 'floors';
    districtView.hidden = floors;
    floorView.hidden = !floors;
    root.dataset.view = floors ? 'floors' : 'districts';
    const fraction = clamp(finite(state.floorShare, 65.2), 0, 100) / 100;
    const unit = Math.max(25, Math.ceil(occupancy / 100 / 25) * 25);
    markerUnit.textContent = `1 метка ≈ ${nf.format(unit)} человек · положения условные`;
    floorViews.forEach((view, i) => {
      const share = i === 0 ? fraction : 1 - fraction;
      const count = occupancy * share;
      const space = areaPerPerson(view.floor.area, count);
      view.people.textContent = nf.format(count);
      view.perPerson.textContent = space === null ? '—' : nf1.format(space);
      view.status.textContent = count ? `${nf1.format(share * 100)}% посетителей` : 'На уровне нет посетителей';
      view.fill.style.width = `${occupancy > 0 ? share * 100 : 0}%`;
      view.svgDesc.textContent = `Площадь пола ${nf1.format(view.floor.area)} квадратных метров. По сценарию ${nf.format(count)} посетителей одновременно, ${space === null ? 'посетителей нет' : nf1.format(space) + ' квадратных метров общей площади на человека'}. Метки не показывают реальные позиции людей.`;
      drawDots(view.dots, view.floor.points, guide * share, solo * share, unit);
    });
  }
  update();
  return {
    update,
    destroy() { destroyed = true; root.remove(); }
  };
}
